#include <cstdio>
#include <algorithm>
using namespace std;

#define ll long long

const int maxn = 1e5 + 5;

int main() {
    int k, x;
    scanf("%d%d", &k, &x);
    int t = min(x + k - 1, 1000000);
    // Using a single printf statement to output the range
    for (int i = max(x - k + 1, -1000000); i <= t; i++) {
        printf("%d%c", i, (i == t) ? '\n' : ' ');
    }
    return 0;
}

